package org.apache.commons.cli;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class OptionsHasOptionTest {

    private Options options;

    @BeforeEach
    public void setUp() {
        options = new Options();
    }

    @Test
    public void testHasOption_shortOptionPresent_variations() throws Exception {
        // put a short option key "a" into private shortOpts map
        putKeyIntoPrivateMap("shortOpts", "a");

        // plain name
        assertTrue(options.hasOption("a"), "should find plain short name");

        // single hyphen
        assertTrue(options.hasOption("-a"), "should find single-hyphen short name");

        // double hyphen
        assertTrue(options.hasOption("--a"), "should find double-hyphen short name");
    }

    @Test
    public void testHasOption_longOptionPresent_variations() throws Exception {
        // put a long option key "verbose" into private longOpts map
        putKeyIntoPrivateMap("longOpts", "verbose");

        // plain name
        assertTrue(options.hasOption("verbose"), "should find plain long name");

        // double hyphen
        assertTrue(options.hasOption("--verbose"), "should find double-hyphen long name");

        // single hyphen also resolves to same cleaned form and should be true
        assertTrue(options.hasOption("-verbose"), "single hyphen should also be accepted");
    }

    @Test
    public void testHasOption_notPresent_and_null_and_empty() throws Exception {
        // ensure maps are empty (fresh instance)
        assertFalse(options.hasOption("missing"), "missing option should return false");

        // null input should not throw and should return false
        assertFalse(options.hasOption(null), "null should be treated as not present");

        // empty string input
        assertFalse(options.hasOption(""), "empty string should be treated as not present");

        // single hyphen alone becomes empty string after stripping and should be false
        assertFalse(options.hasOption("-"), "single hyphen should be treated as not present");
    }

    @Test
    public void testHasOption_bothMapsContainKey_and_multipleHyphens() throws Exception {
        // put the same key in both maps
        putKeyIntoPrivateMap("shortOpts", "x");
        putKeyIntoPrivateMap("longOpts", "x");

        // should return true regardless when key exists in at least one map
        assertTrue(options.hasOption("x"), "key present in both maps should be found");

        // triple-hyphen case: stripLeadingHyphens will remove two hyphens and leave "-x",
        // which won't match "x" unless such key exists; verify behavior is false for "---x"
        assertFalse(options.hasOption("---x"), "three hyphens should not match 'x' (leaves '-x')");
    }

    @SuppressWarnings("unchecked")
    private void putKeyIntoPrivateMap(String fieldName, String key) throws Exception {
        Field field = Options.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Object mapObj = field.get(options);
        if (!(mapObj instanceof Map)) {
            throw new IllegalStateException(fieldName + " is not a Map");
        }
        Map<Object, Object> map = (Map<Object, Object>) mapObj;
        // Value can be any object; Options.hasOption only checks keys
        map.put(key, new Object());
    }
}

